 "glossary": [
  [
   "Biopsy",
   "Removing a small piece of tissue so it can be looked at under a microscope."
  ],
  [
   "Brachytherapy",
   "Radiotherapy given from a source placed inside the body, close to the cancer."
  ],
  [
   "Chemoradiotherapy",
   "Chemotherapy and radiotherapy given during the same period, so the chemotherapy makes the radiotherapy work better."
  ],
  [
   "Colposcopy",
   "A close look at the cervix using a magnifying instrument (a colposcope)."
  ],
  [
   "CT scan",
   "A scan that uses X-rays to make detailed pictures of the inside of the body."
  ],
  [
   "FIGO stage",
   "An international system that describes how far a gynaecological cancer has spread."
  ],
  [
   "HPV",
   "Human papillomavirus. A common virus. Long-lasting infection with some types can lead to cervical cancer."
  ],
  [
   "Hysterectomy",
   "An operation to remove the womb (uterus)."
  ],
  [
   "Immunotherapy",
   "Treatment that helps the body's immune system recognise and attack cancer cells."
  ],
  [
   "Lymph nodes",
   "Small glands that are part of the immune system. Cancer can sometimes spread to them."
  ],
  [
   "MDT",
   "Multidisciplinary team. The group of specialists who meet to plan your care together."
  ],
  [
   "MRI scan",
   "A scan that uses magnets and radio waves to make detailed pictures, especially of soft tissues."
  ],
  [
   "Oncologist",
   "A doctor who specialises in treating cancer."
  ],
  [
   "PARP inhibitor",
   "A tablet treatment that stops cancer cells repairing their DNA. Used for some ovarian cancers."
  ],
  [
   "Pathology",
   "The study of tissue samples in a laboratory to find out what kind of cells are present."
  ],
  [
   "Recurrence",
   "When cancer comes back after treatment."
  ],
  [
   "Sentinel lymph node",
   "The first lymph node (or nodes) that a cancer is most likely to drain to."
  ],
  [
   "Tumour marker",
   "A substance in the blood (such as CA-125 or hCG) that can be raised with some cancers."
  ]
 ],
